function home(){let next=store.lastLesson||'comunicacao-verbal:0', c=D.courses.find(c=>c.id===next.split(':')[0]);return `<section class="hero"><div class="hero-copy"><div class="eyebrow">JORNALISMO · COMUNICAÇÃO · IMAGEM</div><h1>Every street<br>has a story.</h1><p>Transforme Xangai em uma redação, sua câmera em ferramenta de observação e sua voz em uma forma própria de contar o mundo.</p><div class="form-row"><button class="btn accent" data-action="navigate" data-page="academy">Explorar a academia ${ico('arrow')}</button><button class="btn secondary" data-action="navigate" data-page="voice">Treinar minha fala ${ico('mic')}</button></div><div class="hero-statline"><span><strong>${D.courses.length}</strong><small>disciplinas</small></span><span><strong>${D.phrases.length}</strong><small>estruturas verbais</small></span><span><strong>${D.missions.length}</strong><small>missões de campo</small></span></div></div><div class="hero-art"><img src="assets/skyline.svg" alt="Ilustração editorial da cidade de Xangai"></div></section>
${window.StoryLabInteract?window.StoryLabInteract.home():''}
<div class="section-title"><div><div class="eyebrow">COMECE A CONSTRUIR SEU REPERTÓRIO</div><h2>Seu estúdio de aprendizagem</h2></div><span class="hint">Teoria encontra prática</span></div>
<div class="ling-home-feature"><span class="ling-home-emblem">Aa</span><div><div class="eyebrow">NOVO · CIÊNCIA DA LINGUAGEM</div><h3>Desenhe o raciocínio por trás das palavras.</h3><p>Oito dossiês ilustrados com fonética, prosódia, sintaxe, pragmática, discurso, exemplos e exercícios.</p></div><button class="btn accent" data-action="navigate" data-page="linguistics">Explorar linguística ${ico('arrow',15)}</button></div>
<div class="grid grid-4">${actionCard('book','Academia','43 disciplinas e 172 unidades curriculares.','academy')}${actionCard('quote','Fraseoteca','${D.phrases.length} construções em ${D.families.length} famílias de linguagem.','phrases')}${actionCard('mic','Laboratório de fala','48 situações para narrar e improvisar.','voice')}${actionCard('spark','Oficina da Fala','Reformule frases e construa narrações.','clinic')}${actionCard('layers','Atlas Vivo','160 termos e exercícios progressivos de narração.','atlas')}${actionCard('film','Narrador visual','Crie roteiros e pratique as nove camadas.','studio')}</div>
<div class="section-title"><h2>Você está construindo</h2><button class="small-link" data-action="navigate" data-page="progress">Ver minha evolução ${ico('arrow',13)}</button></div><div class="grid grid-4">${stat('Aulas completas',countDone()+' / '+deepCount)}${stat('Frases estudadas',studied())}${stat('Sessões de fala',store.practice.length)}${stat('Missões realizadas',store.missions.length)}</div>
<div class="panel panel-pad" style="margin-top:21px;display:flex;align-items:center;gap:18px;flex-wrap:wrap;justify-content:space-between"><div><div class="eyebrow">PERCURSO PEDAGÓGICO</div><h3 style="margin:8px 0 4px">Uma formação guiada de 12 semanas</h3><p class="muted" style="margin:0">Aulas, repertório oral, gravações e missões em uma sequência que constrói competência.</p></div><button class="btn" data-action="navigate" data-page="journey">Abrir trilha ${ico('arrow')}</button></div><div class="grid grid-2" style="margin-top:21px"><div class="panel panel-pad"><div class="eyebrow">PRÓXIMA AULA</div><h3 style="margin-top:12px">${esc(c?c.title:'Comunicação Verbal')}</h3><p class="muted">Pratique observação, clareza e estruturas de pensamento antes de ligar a câmera.</p><button class="btn" data-action="open-lesson" data-id="${esc(next.split(':')[0])}" data-index="${esc(next.split(':')[1])}">Continuar estudando ${ico('arrow')}</button></div><div class="panel panel-pad"><div class="eyebrow">PRÁTICA DO DIA</div><h3 style="margin-top:12px">Diga mais do que “bonito”</h3><p class="muted">Escolha uma cena, descreva três detalhes e conecte sua observação a uma interpretação honesta.</p><button class="btn secondary" data-action="navigate" data-page="voice">Abrir exercício ${ico('arrow')}</button></div></div>
<div class="notice info" style="margin-top:24px"><strong>Transparência acadêmica.</strong> Nesta edição, ${deepCount} aulas centrais estão integralmente redigidas. As outras disciplinas e unidades já têm ementas e objetivos, mas suas aulas completas ainda serão desenvolvidas. O glossário contém ${D.phrases.length} estruturas autorais iniciais; a meta de milhares de expressões é uma expansão futura.</div>`}
function stat(label,value){return `<div class="panel stat-card"><div class="stat">${esc(value)}</div><div class="label">${esc(label)}</div></div>`}
const SCHOOL_ICON={fundamentos:'book',reportagem:'search',comunicacao:'mic',audiovisual:'film',digital:'layers',editorias:'map'};
function academy(){const school=D.schools.find(s=>s.id===ui.school);let filtered=D.courses.filter(c=>(ui.school==='all'||c.school===ui.school)&&norm(c.title+' '+c.description+' '+c.outcome).includes(norm(ui.courseQuery)));return `${header('ESTRUTURA DE FORMAÇÃO','Academia de Jornalismo','Seis escolas complementares. Cada disciplina contém quatro unidades curriculares, e a comunicação atravessa toda a formação.')}
<div class="grid grid-3" style="margin-bottom:30px">${D.schools.map((s,i)=>`<button class="panel school-tile school-band" data-action="school" data-id="${s.id}" style="--stripe:${s.accent};text-align:left;cursor:pointer"><span class="school-ico" aria-hidden="true">${ico(SCHOOL_ICON[s.id]||'book',26)}</span><div class="school-index">ESCOLA ${String(i+1).padStart(2,'0')}</div><h3>${esc(s.short)}</h3><p>${esc(s.subtitle)}</p><span class="count">${D.courses.filter(c=>c.school===s.id).length} disciplinas ${ico('arrow',14)}</span></button>`).join('')}</div>
<div class="section-title"><h2>${school?esc(school.name):'Todas as disciplinas'}</h2><span class="hint">${filtered.length} encontradas</span></div><div class="filters"><button class="chip-button ${ui.school==='all'?'active':''}" data-action="school" data-id="all">Todas</button>${D.schools.map(s=>`<button class="chip-button ${ui.school===s.id?'active':''}" data-action="school" data-id="${s.id}">${esc(s.short)}</button>`).join('')}</div><div class="form-row" style="margin-bottom:18px"><input class="search" style="max-width:500px" type="search" placeholder="Buscar disciplina, tema ou competência..." aria-label="Buscar disciplinas" data-model="courseQuery" value="${esc(ui.courseQuery)}"></div>
<div class="grid grid-3">${filtered.map(c=>{const s=D.schools.find(s=>s.id===c.school),has=c.modules.every((_,i)=>!!D.deepLessons[c.id+':'+i]);return `<button class="panel course-card school-band" data-action="open-course" data-id="${esc(c.id)}" style="--stripe:${s.accent};text-align:left;cursor:pointer"><div class="row"><span class="chip">${esc(s.short)}</span><span class="chip ${has?'accent':''}">${has?'4 aulas completas':(D.deepLessons[c.id+':0']?'Aulas em desenvolvimento':'Plano curricular')}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="footer"><span class="muted small">4 unidades</span><span class="small-link">Explorar ${ico('arrow',14)}</span></div></button>`}).join('')}</div>${filtered.length?'':`<div class="empty"><h3>Nenhuma disciplina encontrada</h3><p>Experimente outra palavra ou escola.</p></div>`}`}
function courseView(){const c=D.courses.find(c=>c.id===ui.courseId);if(!c)return academy();const s=D.schools.find(s=>s.id===c.school);return `<div class="breadcrumb"><button data-action="navigate" data-page="academy">Academia</button>${ico('chevron',12)}<span>${esc(s.short)}</span>${ico('chevron',12)}<strong>${esc(c.title)}</strong></div>${header('DISCIPLINA / '+s.short,c.title,c.description,`<span class="chip">4 unidades curriculares</span>`)}<div class="two-col"><div><div class="eyebrow" style="margin-bottom:14px">PLANO DE APRENDIZAGEM</div><div class="lesson-roadmap">${c.modules.map((m,i)=>{let full=!!D.deepLessons[c.id+':'+i],done=store.completed.includes(c.id+':'+i);return `<button class="lesson-row" data-action="open-lesson" data-id="${c.id}" data-index="${i}"><span class="n">${String(i+1).padStart(2,'0')}</span><span class="grow"><strong>${esc(m.title)}</strong><small>${full?'Aula completa com teoria, exemplos e prática':'Ementa e prática previstas — conteúdo aprofundado pendente'}</small></span><span class="chip ${done?'accent':''}">${done?'Concluída':full?'Estudar':'Plano'}</span>${ico('chevron')}</button>`}).join('')}</div></div><aside class="side-help"><div class="panel panel-pad"><div class="eyebrow">COMPETÊNCIA-ALVO</div><h3 style="margin-top:15px">Ao concluir, você deverá...</h3><p>${esc(c.outcome)}</p><div class="divider"></div><p class="muted small">As unidades marcadas como “Plano” apresentam o percurso do curso, mas ainda não são contabilizadas como aulas completas.</p><button class="btn secondary" data-action="navigate" data-page="phrases">Abrir fraseoteca ${ico('arrow')}</button></div></aside></div>`}
// Esquemas explicativos da aula (desenhados por illustrations.js a partir de D.figures)
function figureHtml(key,i){const f=(D.figures||{})[key];return f&&f[i]&&window.StoryLabFigures?window.StoryLabFigures.render(f[i]):''}
function lessonView(){const c=D.courses.find(c=>c.id===ui.courseId);if(!c)return academy();const index=Math.max(0,Math.min(3,Number(ui.module)||0)),m=c.modules[index],key=c.id+':'+index,deep=D.deepLessons[key],done=store.completed.includes(key);return `<div class="breadcrumb"><button data-action="navigate" data-page="academy">Academia</button>${ico('chevron',12)}<button data-action="open-course" data-id="${c.id}">${esc(c.title)}</button>${ico('chevron',12)}<span>Unidade ${index+1}</span></div><div class="lesson-body">${header(`UNIDADE ${String(index+1).padStart(2,'0')} / ${deep?'AULA COMPLETA':'ROTEIRO CURRICULAR'}`,deep?deep.title:m.title,deep?deep.intro:c.description)}</div>
${window.StoryLabLinguistics?window.StoryLabLinguistics.relatedTo(c.id):''}<div class="two-col"><article class="stack lesson-body">${deep?`<div class="notice info">${ico('book',15)} Esta unidade contém material didático integral: explicação, demonstrações, atividade prática e critérios de revisão.</div>${figureHtml(key,0)}${deep.steps.map((step,i)=>`<section class="panel step"><div class="n">CONCEITO ${String(i+1).padStart(2,'0')}</div><h3>${esc(step.title)}</h3><p>${esc(step.body)}</p><div class="example"><strong>Exemplo aplicado</strong><div>${esc(step.example)}</div></div></section>`).join('')}${figureHtml(key,1)}${figureHtml(key,2)}<div class="panel panel-pad"><div class="eyebrow">OFICINA DE CAMPO</div><h3 style="margin-top:11px">Transforme teoria em competência</h3><p>${esc(deep.assignment)}</p><div class="notice info"><strong>Autoverificação:</strong> ${esc(deep.rubric)}</div><div class="row" style="margin-top:18px;flex-wrap:wrap"><button class="btn ${done?'secondary':'accent'}" data-action="complete-lesson" data-id="${esc(key)}">${ico('check')} ${done?'Marcar como não concluída':'Concluir esta aula'}</button><button class="btn secondary" data-action="navigate" data-page="clinic">Oficina da Fala ${ico('spark')}</button><button class="btn secondary" data-action="navigate" data-page="voice">Gravar ${ico('mic')}</button></div></div>`:`<div class="notice">Esta unidade é parte do planejamento acadêmico. O conteúdo aprofundado ainda não foi redigido e por isso não pode ser marcado como aula concluída.</div><section class="panel panel-pad"><div class="eyebrow">OBJETIVO DA UNIDADE</div><h3 style="margin-top:14px">${esc(m.title)}</h3><p>${esc(c.description)}</p><div class="divider"></div><div class="eyebrow">ATIVIDADE-ALVO</div><p style="margin-top:11px">${esc(c.outcome)}</p><div class="notice info">Um roteiro curricular não equivale a uma aula integral. O programa está disponível para orientar futuros módulos.</div></section>`}</article><aside class="side-help stack"><div class="panel panel-pad"><div class="eyebrow">NAVEGAÇÃO DA DISCIPLINA</div><div class="stack" style="gap:8px;margin-top:15px">${c.modules.map((mod,i)=>`<button class="btn ${i===index?'':'secondary'} sm" style="justify-content:flex-start;text-align:left;white-space:normal" data-action="open-lesson" data-id="${c.id}" data-index="${i}">${String(i+1).padStart(2,'0')} · ${esc(mod.title)}</button>`).join('')}</div></div><div class="panel panel-pad"><div class="eyebrow">COMUNICAÇÃO INTEGRADA</div><p style="margin-top:10px" class="muted small">Após estudar, explique o conceito como se estivesse ensinando uma pessoa que nunca teve contato com o tema. Faça uma versão em 30 e outra em 90 segundos.</p><button class="btn secondary sm" data-action="navigate" data-page="studio">Abrir narrador ${ico('arrow')}</button></div></aside></div>`}

const CLINIC_SCENES=[
 ['Rua arborizada','Descrever a vegetação, a relação entre fachadas e o movimento sem inventar a história do lugar.'],
 ['Vitrine de moda','Relacionar composição, materiais e caimento sem atribuir intenções à marca sem fonte.'],
 ['Cafeteria de bairro','Transformar aroma, som, luz e ações observáveis numa cena narrável.'],
 ['Metrô de Xangai','Apresentar o percurso e suas condições sem generalizar o funcionamento de toda a rede.'],
 ['Mercado e comércio','Construir uma narrativa de consumo, preço ou atendimento com fonte e recorte claros.'],
 ['Fotografia de arquitetura','Explicar forma, escala, perspectiva e iluminação de um edifício.'],
 ['Cena noturna','Construir atmosfera com movimentos, reflexos e sons do ambiente.'],
 ['Produto de tecnologia','Explicar demonstração, resultado observado e limites de um teste pessoal.']
];
function clinicSentence(x){return String(x||'').trim().replace(/[.!?;:,\s]+$/,'').slice(0,1000)}
function composeClinic(){
 const f=ui.clinicInputs;
 const obs=clinicSentence(f.observation),det=clinicSentence(f.detail),ctx=clinicSentence(f.context),src=clinicSentence(f.source),refl=clinicSentence(f.reflection);
 if(obs.length<8||det.length<8){toast('Escreva uma observação e um detalhe concretos antes de construir.');return}
 const scene=CLINIC_SCENES[ui.clinicScene][0];
 const pieces={
  documental:[`Neste registro sobre ${scene.toLowerCase()}, ${obs.charAt(0).toLowerCase()+obs.slice(1)}.`,`Um detalhe que merece atenção: ${det.charAt(0).toLowerCase()+det.slice(1)}.`],
  espontaneo:[`Estou observando ${scene.toLowerCase()} e uma coisa me chamou a atenção: ${obs.charAt(0).toLowerCase()+obs.slice(1)}.`,`Reparem também neste detalhe: ${det.charAt(0).toLowerCase()+det.slice(1)}.`],
  didatico:[`Vamos observar ${scene.toLowerCase()} por dois aspectos. Primeiro: ${obs.charAt(0).toLowerCase()+obs.slice(1)}.`,`Segundo: ${det.charAt(0).toLowerCase()+det.slice(1)}.`],
  contemplativo:[`A cena começa por um detalhe concreto: ${obs.charAt(0).toLowerCase()+obs.slice(1)}.`,`Quando olhamos com mais atenção, percebemos outro: ${det.charAt(0).toLowerCase()+det.slice(1)}.`]
 };
 const lines=[...(pieces[f.style]||pieces.documental)];
 if(ctx){
  if(f.status==='documentado'&&src.length>=4){lines.push(`Segundo a fonte informada (${src}), ${ctx.charAt(0).toLowerCase()+ctx.slice(1)}.`)}
  else {lines.push(`Há uma informação que ainda precisa ser confirmada antes da publicação: ${ctx}.`)}
 }
 if(refl){lines.push(`Minha leitura pessoal é a seguinte: ${refl.charAt(0).toLowerCase()+refl.slice(1)}.`)}
 else lines.push('O que essa observação pode nos ensinar? É uma pergunta que vale acompanhar.');
 ui.clinicGenerated=lines.join('\n\n');
 render();
 toast('Estrutura construída. Releia e verifique antes de publicar.');
}
function clinicView(){
 const f=ui.clinicInputs,scene=CLINIC_SCENES[ui.clinicScene],drill=D.speechDrills[ui.clinicDrill];
 const fields=[['observation','1 · O que você observou de fato?','Ex.: As árvores projetam sombras sobre quase toda a calçada'],['detail','2 · Qual é o detalhe específico?','Ex.: Os relevos da fachada aparecem quando a luz passa pelas folhas'],['context','3 · Contexto opcional','Informação para apurar, sem inventar datas, razões ou números'],['source','4 · Fonte consultada (se houver)','Ex.: placa no local, página institucional, entrevista com consentimento'],['reflection','5 · Sua interpretação (sempre sinalizada)','Ex.: Para mim, essa escala torna a caminhada mais acolhedora']];
 return `${header('LABORATÓRIO / PERFORMANCE E RACIOCÍNIO','Oficina da Fala','Transforme observações em narrações e aprenda a substituir falas vagas por comunicação precisa, expressiva e verificável.')}
 <div class="grid grid-4" style="margin-bottom:20px">${stat('Aulas de comunicação completas',D.courses.filter(c=>c.school==='comunicacao').reduce((a,c)=>a+c.modules.filter((_,i)=>D.deepLessons[c.id+':'+i]).length,0)+' / 40')}${stat('Exercícios de reformulação',D.speechDrills.length)}${stat('Roteiros locais',store.clinicDrafts.length)}${stat('Transformações praticadas',store.clinicDone.length)}</div>
 <div class="filters" role="tablist" aria-label="Ferramentas da oficina"><button class="chip-button ${ui.clinicTab==='compose'?'active':''}" data-action="clinic-tab" data-id="compose">${ico('edit',14)} Montar narração</button><button class="chip-button ${ui.clinicTab==='drill'?'active':''}" data-action="clinic-tab" data-id="drill">${ico('refresh',14)} Reformular e melhorar</button></div>
 ${ui.clinicTab==='compose'?`<div class="two-col"><div class="stack"><div class="panel panel-pad"><div class="eyebrow">CONSTRUTOR DE RACIOCÍNIO</div><h2 style="font-family:Georgia,serif;font-size:26px;margin:9px 0 13px">Da cena ao discurso</h2><div class="notice info">O aplicativo organiza somente informações que você escrever. Ele <strong>não verifica automaticamente fatos</strong> nem inventa datas, nomes ou fontes.</div><div class="grid grid-2" style="margin:20px 0"><div><label class="field-label" for="clinic-scene">Situação</label><select id="clinic-scene" data-clinic-select="scene">${CLINIC_SCENES.map((c,i)=>`<option value="${i}" ${ui.clinicScene===i?'selected':''}>${esc(c[0])}</option>`).join('')}</select></div><div><label class="field-label" for="clinic-style">Registro de fala</label><select id="clinic-style" data-clinic-select="style">${[['documental','Documental'],['espontaneo','Vlog espontâneo'],['didatico','Explicativo'],['contemplativo','Contemplativo']].map(([v,l])=>`<option value="${v}" ${f.style===v?'selected':''}>${l}</option>`).join('')}</select></div></div>${fields.map(([key,label,ph])=>`<div style="margin-bottom:17px"><label class="field-label" for="clinic-${key}">${label}</label><textarea class="field" id="clinic-${key}" data-clinic-field="${key}" rows="2" maxlength="1000" placeholder="${esc(ph)}">${esc(f[key])}</textarea></div>`).join('')}<div style="margin-bottom:18px"><label class="field-label" for="clinic-status">Status da informação de contexto</label><select id="clinic-status" data-clinic-select="status"><option value="pendente" ${f.status==='pendente'?'selected':''}>Não confirmada — inserir como informação a verificar</option><option value="documentado" ${f.status==='documentado'?'selected':''}>Documentada por mim — exige nome de fonte</option></select></div><div class="form-row"><button class="btn accent" data-action="clinic-build">${ico('spark')} Construir narração</button><button class="btn secondary" data-action="clinic-clear">Limpar campos</button></div></div>${ui.clinicGenerated?`<div class="panel panel-pad"><div class="eyebrow">PRIMEIRA VERSÃO · REVISÃO OBRIGATÓRIA</div><h3 style="margin:12px 0">Narração estruturada</h3><div class="output" id="clinic-output">${esc(ui.clinicGenerated)}</div><div class="notice">Modelo para praticar: revise conteúdo, sequência e tom. Um texto que menciona uma fonte informada por você não significa que o aplicativo a verificou.</div><div class="form-row" style="margin-top:15px"><button class="btn accent" data-action="clinic-save">${ico('check')} Salvar roteiro</button><button class="btn secondary" data-action="clinic-copy">${ico('copy')} Copiar</button><button class="btn secondary" data-action="clinic-speak">${ico('volume')} Ouvir</button><button class="btn secondary" data-action="clinic-to-tele">${ico('film')} Teleprompter</button></div></div>`:''}</div><aside class="side-help stack"><div class="panel panel-pad"><div class="eyebrow">PAUTA DE CAMPO</div><h3 style="margin:12px 0">${esc(scene[0])}</h3><p class="muted">${esc(scene[1])}</p><div class="divider"></div><div class="eyebrow">CHECKLIST DE PUBLICAÇÃO</div><ul class="clinic-tips"><li>Separou observação de interpretação?</li><li>Há evidência para cada dado factual?</li><li>O texto descreve o que foi filmado?</li><li>Imagens de terceiros respeitam privacidade?</li><li>O encerramento responde à pergunta inicial?</li></ul><button class="btn secondary sm" data-action="clinic-tab" data-id="drill">Treinar reformulação ${ico('arrow',13)}</button></div>${store.clinicDrafts.length?`<div class="panel panel-pad"><div class="eyebrow">ROTEIROS SALVOS NESTE NAVEGADOR</div><div class="stack" style="gap:12px;margin-top:15px">${store.clinicDrafts.slice().reverse().slice(0,8).map((item,idx)=>`<div class="clinic-saved"><strong>${esc(item.scene)}</strong><div class="small muted">${esc(new Date(item.at).toLocaleDateString('pt-BR'))} · ${esc(item.style)}</div><p class="small muted">${esc(item.text.slice(0,145))}...</p><div class="form-row"><button class="btn secondary sm" data-action="clinic-restore" data-id="${store.clinicDrafts.length-1-idx}">Abrir</button><button class="btn secondary sm" data-action="clinic-delete" data-id="${store.clinicDrafts.length-1-idx}">Excluir</button></div></div>`).join('')}</div></div>`:''}</aside></div>`:
 `<div class="two-col"><article class="stack"><div class="panel panel-pad"><div class="row" style="justify-content:space-between;gap:12px"><span class="eyebrow">CARTÃO ${String(ui.clinicDrill+1).padStart(2,'0')} / ${D.speechDrills.length}</span><span class="chip ${store.clinicDone.includes(drill.id)?'accent':''}">${store.clinicDone.includes(drill.id)?'Já praticado':'Pendente'}</span></div><h2 style="font-family:Georgia,serif;margin:15px 0;font-size:28px">${esc(drill.topic)}</h2><div class="clinic-before"><div class="eyebrow">FALA INICIAL · MELHORE ANTES DE REVELAR</div><p>${esc(drill.weak)}</p></div><div class="notice info">${ico('mic',14)} ${esc(drill.challenge)} Tente falar sua própria versão em voz alta antes de revelar o modelo.</div><div class="form-row" style="margin:19px 0 4px"><button class="btn accent" data-action="clinic-reveal">${ui.clinicReveal?'Esconder exemplo':'Revelar transformação'} ${ico('arrow',14)}</button><button class="btn secondary" data-action="clinic-next">Próximo desafio ${ico('shuffle',14)}</button></div>${ui.clinicReveal?`<div class="clinic-after"><div class="eyebrow">FORMULAÇÃO MAIS PRECISA</div><p>${esc(drill.strong)}</p><div class="divider"></div><strong>Por que funciona</strong><p class="small muted">${esc(drill.why)}</p><button class="btn secondary sm" data-action="clinic-read-example">${ico('volume',13)} Ouvir exemplo</button></div><div class="form-row"><button class="btn accent" data-action="clinic-mark">${ico('check')} ${store.clinicDone.includes(drill.id)?'Revisar novamente':'Marcar como praticado'}</button><button class="btn secondary" data-action="clinic-phrase-link">${ico('quote')} Estudar frases</button></div>`:''}</div></article><aside class="side-help stack"><div class="panel panel-pad"><div class="eyebrow">MÉTODO</div><h3 style="margin:10px 0">Quatro movimentos</h3><ol class="clinic-tips"><li>Reconheça o problema da primeira frase.</li><li>Produza uma versão sem olhar a resposta.</li><li>Compare seu texto com o modelo explicado.</li><li>Grave sua própria frase e repita outro dia.</li></ol><p class="small muted">Os exemplos são modelos editoriais, não uma avaliação automática da sua fala.</p></div><div class="panel panel-pad"><div class="eyebrow">PROGRESSO NESTA OFICINA</div><h3 style="margin:13px 0">${store.clinicDone.length} de ${D.speechDrills.length} exercícios</h3><div class="metric-bar"><span style="width:${percentage(store.clinicDone.length,D.speechDrills.length)}%"></span></div></div></aside></div>`}
 <div class="notice info" style="margin-top:26px">Seus roteiros ficam salvos apenas neste navegador, junto com o progresso existente. Exporte regularmente um backup em <strong>Minha Evolução</strong> para não perder suas anotações.</div>`;
}

