function voiceView(){let ch=D.challenges[ui.challenge]||D.challenges[0];let tally=store.practice.length;let rec=!!ui.recordUrl;return `${header('LABORATÓRIO DE IMPROVISAÇÃO','Estúdio da Voz','Aprenda a organizar pensamentos e falar espontaneamente: descreva, compare, explique e conclua. A gravação permanece apenas nesta sessão, a menos que você a salve por conta própria.')}
<div class="two-col"><div class="stack"><div class="record-stage"><div class="eyebrow" style="color:#e6a782">DESAFIO ${String(ui.challenge+1).padStart(2,'0')} / ${D.challenges.length}</div><h2 style="margin:11px 0">${esc(ch.scene)}</h2><p>${esc(ch.brief)}</p><div class="timer" id="record-timer">${ui.recording?formatSecs(ui.recordElapsed):formatSecs(ch.seconds)}</div><div class="small" style="color:#9bb0af">${ui.recording?'Tempo decorrido':'Duração sugerida'} · modo ${esc(ch.mode)}</div><button class="record ${ui.recording?'active':''}" aria-label="${ui.recording?'Parar gravação':'Iniciar gravação'}" data-action="record">${ico(ui.recording?'pause':'mic',28)}</button><div class="form-row" style="justify-content:center"><button class="btn secondary sm" data-action="new-challenge">${ico('shuffle',14)} Novo desafio</button><button class="btn secondary sm" data-action="navigate" data-page="studio">${ico('layers',14)} Construir roteiro</button></div>${ui.voiceError?`<p style="margin-top:15px;color:#ffc1b8">${esc(ui.voiceError)}</p>`:''}</div>
${rec?`<div class="panel panel-pad"><div class="eyebrow">OUÇA SUA GRAVAÇÃO</div><audio controls src="${esc(ui.recordUrl)}" style="width:100%;margin-top:13px"></audio><p class="small muted">O áudio não é enviado para servidores nem incluído no progresso salvo. Faça o download aqui antes de fechar a página, caso queira guardá-lo.</p><div class="form-row"><button class="btn secondary sm" data-action="download-record">${ico('download')} Salvar áudio</button><button class="btn secondary sm" data-action="remove-record">Descartar gravação</button></div></div>`:''}
<div class="panel panel-pad"><div class="eyebrow">AUTOVALIAÇÃO GUIADA</div><h3 style="margin-top:10px">Não avalie apenas velocidade</h3><p class="muted">Dê notas de 1 a 5 para cada competência. Registre uma sessão para acompanhar a evolução.</p><div class="scale-grid">${['Clareza','Precisão','Progressão','Expressividade'].map((v,i)=>`<div class="scale-field"><label for="rubric-${i}">${v}</label><input id="rubric-${i}" data-rubric="${i}" type="range" min="1" max="5" step="1" value="${ui.voiceRubric[i]}"><div class="row"><span>1 · Inicial</span><strong id="rubric-label-${i}">${ui.voiceRubric[i]}/5</strong><span>5 · Forte</span></div></div>`).join('')}</div><label class="field-label" for="takeaway" style="margin-top:19px">Uma melhoria para a próxima gravação (opcional)</label><textarea class="field" id="takeaway" placeholder="Ex.: manter uma ideia por frase e mencionar dois detalhes concretos."></textarea><button class="btn accent" data-action="save-practice" style="margin-top:15px">${ico('check')} Registrar sessão</button></div></div>
<aside class="stack"><div class="panel panel-pad"><div class="eyebrow">COMO EXECUTAR</div><h3 style="margin-top:11px">Quatro movimentos de fala</h3><div class="stack" style="margin-top:16px;gap:17px">${[['01','Apresente','Nomeie a situação em uma frase.'],['02','Detalhe','Traga elementos observáveis.'],['03','Conecte','Compare, explique ou contextualize.'],['04','Feche','Conclua sem generalizações indevidas.']].map(s=>`<div class="row-start" style="align-items:flex-start"><span class="chip accent">${s[0]}</span><div><strong>${s[1]}</strong><div class="muted small">${s[2]}</div></div></div>`).join('')}</div></div><div class="panel panel-pad"><div class="eyebrow">CONTROLE DE APRENDIZAGEM</div><h3 style="margin-top:11px">${tally} sessões registradas</h3><p class="muted small">As notas são autoavaliações, não pontuações calculadas por inteligência artificial. Para comparar duas sessões, mantenha critérios semelhantes.</p><button class="btn secondary sm" data-action="navigate" data-page="progress">Ver histórico ${ico('arrow')}</button></div><div class="notice info"><strong>Privacidade:</strong> o microfone só é solicitado quando você inicia uma gravação. O navegador pode pedir permissão; a captura exige um contexto seguro e suporte a MediaRecorder. A prática continua disponível mesmo sem acesso ao microfone.</div></aside></div>`}
function formatSecs(n){let v=Math.max(0,Math.floor(n));return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`}
function builderResult(){const b=ui.builder;const a=(s)=>String(s||'').trim().replace(/[.!?…]+$/,'');let pieces=[];
 if(b.style==='poetico')pieces.push(`Há histórias que começam em pequenos detalhes.${b.place?' Hoje, estou '+a(b.place)+'.':''}`);
 else if(b.style==='espontaneo')pieces.push(`Hoje estou ${b.place?a(b.place):'explorando um ambiente'} e quero mostrar o que encontrei.`);
 else if(b.style==='didatico')pieces.push(`${b.place?'Estamos '+a(b.place)+'. ':''}Vamos observar alguns elementos desta cena e entender por que eles importam.`);
 else pieces.push(`Estamos ${b.place?a(b.place):'diante de uma cena'} que merece um olhar mais atento.`);
 if(b.observation)pieces.push(`A primeira coisa que observo é ${a(b.observation)}.`);
 if(b.detail)pieces.push(`O detalhe que merece atenção é ${a(b.detail)}.`);
 if(b.context)pieces.push(`Para compreender melhor o contexto, ainda precisamos verificar ou atribuir: ${a(b.context)}.`);
 if(b.contrast)pieces.push(`Uma comparação possível, se feita com critérios equivalentes, é ${a(b.contrast)}.`);
 if(b.reflection)pieces.push(`Minha interpretação pessoal é ${a(b.reflection)}.`);
 else pieces.push('O que esta cena nos permite concluir — e o que ainda precisamos investigar?');
 return pieces.join('\n\n')}
function studioView(){return `${header('ROTEIRO E LINGUAGEM','Estúdio Narrativo','Transforme observações em uma fala coerente, experimente estilos, domine as nove camadas e ensaie sua apresentação com teleprompter.')}
<div class="filters">${[['builder','Construtor de narração'],['layers','Nove camadas'],['tele','Teleprompter']].map(([v,n])=>`<button class="chip-button ${ui.studioTab===v?'active':''}" data-action="studio-tab" data-id="${v}">${esc(n)}</button>`).join('')}</div>
${ui.studioTab==='builder'?`<div class="two-col"><div class="panel panel-pad"><div class="eyebrow">NARRAÇÃO BASEADA NAS SUAS OBSERVAÇÕES</div><h3 style="margin:12px 0 20px">Do que você realmente viu ao que deseja comunicar</h3><div class="grid grid-2">${[['place','Onde você está? (inclua a preposição)','Ex.: na Rua Wukang, em Xangai'],['observation','O que observa?','Ex.: as copas das árvores se encontram'],['detail','Qual detalhe revela a cena?','Ex.: a luz desenha formas sobre a calçada'],['context','Que contexto deve verificar?','Ex.: quando a rua recebeu a arborização'],['contrast','O que pode comparar?','Ex.: o movimento desta rua com a avenida próxima'],['reflection','Qual sua leitura pessoal?','Ex.: a escala do lugar me parece acolhedora']].map(([key,label,placeholder])=>`<div><label class="field-label" for="b-${key}">${label}</label><textarea rows="2" class="field" data-builder="${key}" id="b-${key}" placeholder="${esc(placeholder)}">${esc(ui.builder[key])}</textarea></div>`).join('')}</div><label class="field-label" style="margin-top:16px">Estilo de comunicação</label><select data-builder="style">${[['documental','Documental'],['espontaneo','Vlogger espontâneo'],['poetico','Contemplativo'],['didatico','Didático']].map(([k,v])=>`<option value="${k}" ${ui.builder.style===k?'selected':''}>${v}</option>`).join('')}</select><div class="form-row" style="margin-top:15px"><button class="btn accent" data-action="generate-script">${ico('spark')} Construir narração</button><button class="btn secondary" data-action="builder-clear">Limpar campos</button></div></div><aside class="stack"><div class="panel panel-pad"><div class="eyebrow">ROTEIRO GERADO</div><h3 style="margin-top:12px">Um ponto de partida, não uma conclusão automática</h3><div class="output" id="script-output">${esc(ui.script||'Preencha as suas observações e toque em “Construir narração”. Nada será inventado sobre o local.')}</div><div class="form-row" style="margin-top:15px"><button class="btn secondary sm" data-action="copy-script">${ico('copy')} Copiar</button><button class="btn secondary sm" data-action="script-to-tele">${ico('play')} Enviar ao teleprompter</button><button class="btn secondary sm" data-action="speak-script">${ico('volume')} Ouvir</button></div></div><div class="notice info"><strong>Princípio editorial:</strong> o construtor usa apenas o que você informou. Informações históricas ou numéricas incluídas no campo de contexto são marcadas como pendentes de verificação ou atribuição.</div></aside></div>`:''}
${ui.studioTab==='layers'?`<div class="two-col"><div><div class="eyebrow" style="margin-bottom:15px">ESCADA DE PROFUNDIDADE NARRATIVA</div>${D.layers.map((l,i)=>`<div class="layer-card"><div class="row"><strong>${String(i+1).padStart(2,'0')} · ${esc(l.title)}</strong><span class="chip">Camada ${i+1}</span></div><p class="question">${esc(l.question)}</p><p class="example">“${esc(l.example)}”</p></div>`).join('')}</div><aside class="side-help"><div class="panel panel-pad"><h3>Como estudar as camadas</h3><p class="muted">Descreva uma cena usando apenas as primeiras três camadas. Depois, adicione espaço, informação verificada e comparação. Feche com sua interpretação, uma presença humana e síntese.</p><p class="small muted">As nove camadas são uma metodologia autoral de treino, não uma teoria acadêmica universal.</p><button class="btn" data-action="navigate" data-page="voice">Praticar em voz alta ${ico('arrow')}</button></div></aside></div>`:''}
${ui.studioTab==='tele'?`<div class="two-col"><div class="stack"><div class="panel panel-pad"><label class="field-label" for="teleText">Seu texto</label><textarea class="field" id="teleText" data-model="teleText" rows="6" placeholder="Cole ou escreva o seu roteiro...">${esc(ui.teleText)}</textarea><div class="grid grid-2" style="margin-top:13px"><div><label class="field-label">Modo de apoio</label><select data-model="teleMode"><option value="full" ${ui.teleMode==='full'?'selected':''}>Texto completo</option><option value="keywords" ${ui.teleMode==='keywords'?'selected':''}>Palavras-chave</option><option value="blank" ${ui.teleMode==='blank'?'selected':''}>Sem texto (improviso)</option></select></div><div><label class="field-label">Velocidade da rolagem · ${ui.teleSpeed}</label><input type="range" min="1" max="7" data-model="teleSpeed" value="${ui.teleSpeed}" style="width:100%;margin-top:11px"></div></div></div><div class="prompter" id="prompter"><div class="prompter-inner" id="prompter-inner">${esc(teleDisplay())}</div></div><div class="form-row"><button class="btn accent" data-action="tele-toggle">${ico(ui.telePlaying?'pause':'play')} ${ui.telePlaying?'Pausar':'Iniciar'} rolagem</button><button class="btn secondary" data-action="tele-reset">Reiniciar</button></div></div><aside class="side-help"><div class="panel panel-pad"><div class="eyebrow">RETIRADA PROGRESSIVA DO APOIO</div><h3 style="margin-top:12px">Treine sem decorar</h3><p class="muted">Faça uma leitura completa, depois selecione palavras-chave e finalmente fale sem texto. O objetivo é preservar as ideias, não a ordem exata das palavras.</p><div class="notice info">A rolagem ocorre no seu navegador. A velocidade é aproximada; ajuste ao ritmo da sua leitura.</div></div></aside></div>`:''}`}
function teleDisplay(){if(ui.teleMode==='blank')return 'Olhe para a lente.\n\nRespire.\n\nApresente uma ideia por vez.';if(ui.teleMode==='keywords')return ui.teleText.split(/\n+/).map(x=>x.trim().split(/\s+/).slice(0,5).join(' ')).join('\n\n')||'Escreva seu roteiro para extrair palavras-chave.';return ui.teleText||'Escreva seu roteiro para iniciar a prática.'}
let teleFrame=null,teleLast=0;function stopTele(){ui.telePlaying=false;if(teleFrame)cancelAnimationFrame(teleFrame);teleFrame=null}
function runTele(t){if(!ui.telePlaying)return;const el=document.getElementById('prompter');if(!el)return;let dt=teleLast?Math.min(t-teleLast,60):0;teleLast=t;el.scrollTop+=ui.teleSpeed*dt/42;if(el.scrollTop>=el.scrollHeight-el.clientHeight){stopTele();return}teleFrame=requestAnimationFrame(runTele)}
