function journeyView(){let completeWeeks=JOURNEY.filter(w=>w.lessons.every(id=>store.completed.includes(id+':0'))&&store.missions.includes(w.mission)).length;return `${header('PLANO DE ESTUDOS ORIENTADO','Sua trilha de 12 semanas','Uma proposta de formação intensiva e adaptável: teoria, prática oral e missão de campo. O ritmo sugerido é de 4 sessões semanais; nenhuma semana expira.',`<span class="chip accent">${completeWeeks}/12 marcos atingidos</span>`)}<div class="notice info" style="margin-bottom:24px"><strong>Como funciona:</strong> em cada semana, estude a aula ou as aulas indicadas, pratique a família de frases, grave um desafio de voz e realize uma missão. O marco aparece como atingido quando as aulas indicadas e a missão estão marcadas como concluídas. O exercício de fala é recomendado, não aferido automaticamente.</div><div class="grid grid-2">${JOURNEY.map((w,i)=>{let ls=w.lessons.map(id=>D.courses.find(c=>c.id===id)).filter(Boolean),m=D.missions.find(m=>m.id===w.mission),complete=w.lessons.every(id=>store.completed.includes(id+':0'))&&store.missions.includes(w.mission);return `<div class="panel panel-pad" style="border-top:3px solid ${complete?'#638a78':'#c78969'}"><div class="row"><span class="eyebrow">SEMANA ${String(i+1).padStart(2,'0')}</span><span class="chip ${complete?'accent':''}">${complete?'Marco atingido':'Em desenvolvimento'}</span></div><h3 style="font-family:Georgia,serif;font-size:26px;margin:15px 0 8px">${esc(w.name)}</h3><p class="muted" style="min-height:58px">${esc(w.goal)}</p><div class="divider"></div><div class="small muted" style="font-weight:750;margin-bottom:9px">AULAS INTEGRAIS</div><div class="stack" style="gap:7px">${ls.map(c=>`<button class="btn secondary sm" style="justify-content:flex-start;text-align:left" data-action="open-lesson" data-id="${c.id}" data-index="0">${store.completed.includes(c.id+':0')?ico('check',14):ico('book',14)} ${esc(c.title)}</button>`).join('')}</div><div class="small muted" style="font-weight:750;margin:15px 0 8px">APLICAÇÃO</div><p class="small" style="margin-bottom:12px">${esc(w.drill)}</p><div class="form-row"><button class="btn secondary sm" data-action="journey-phrase" data-id="${w.family}">${ico('quote',13)} Frases</button><button class="btn secondary sm" data-action="open-mission" data-id="${m.id}">${store.missions.includes(m.id)?ico('check',13):ico('map',13)} Missão</button><button class="btn secondary sm" data-action="navigate" data-page="voice">${ico('mic',13)} Falar</button></div></div>`}).join('')}</div><div class="notice info" style="margin-top:24px">Este é um percurso inicial de competências, não equivalente à carga horária de uma graduação. As 43 disciplinas continuam disponíveis na academia para estudo paralelo e aprofundamento.</div>`}
function renderPage(){switch(ui.page){case 'academy':return academy();case 'linguistics':return window.StoryLabLinguistics?window.StoryLabLinguistics.render():'<div class="notice">Biblioteca linguística em inicialização.</div>';case 'journey':return journeyView();case 'course':return courseView();case 'lesson':return lessonView();case 'phrases':return phrasesView();case 'clinic':return clinicView();case 'voice':return voiceView();case 'studio':return studioView();case 'atlas':return atlasView();case 'trade':return window.StoryLabTrade?window.StoryLabTrade.render():'<div class="notice">Repertório profissional em inicialização.</div>';case 'field':return fieldView();case 'mission':return missionView();case 'progress':return progressView();default:return home()}}
function render(preserveFocus=false){let focus=null,sel=null;const e=document.activeElement;if(preserveFocus&&e&&e.dataset.model){focus=e.dataset.model;if(typeof e.selectionStart==='number')sel=[e.selectionStart,e.selectionEnd]}document.documentElement.dataset.theme=store.theme;document.getElementById('app').innerHTML=shell(renderPage());window.StoryLabAudio?.enhance(document.getElementById('app'));if(focus){const node=document.querySelector(`[data-model="${focus}"]`);if(node){node.focus();if(sel&&node.setSelectionRange)try{node.setSelectionRange(...sel)}catch{}}}const off=document.getElementById('offline-state');if(off)off.style.display=navigator.onLine?'none':'inline-flex'}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.')}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();try{document.execCommand('copy');toast('Texto copiado.')}catch{toast('Não foi possível copiar neste navegador.')}t.remove()}}
function say(text,lang='pt-BR'){if(window.StoryLabAudio)return window.StoryLabAudio.speak(text,lang,'Repertório de narração');if(!('speechSynthesis'in window)){toast('Este navegador não oferece síntese de voz.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=.92;u.pitch=1;speechSynthesis.speak(u)}
function reviewPhrase(id){const before=store.reviews[id]||{level:0,count:0};const level=Math.min(5,before.level+1);const intervals=[0,1,3,7,14,30];store.reviews[id]={level,count:before.count+1,last:Date.now(),next:Date.now()+intervals[level]*86400000};save();toast(`Frase estudada · próxima revisão em ${intervals[level]} dia(s).`);render()}
let recorder=null,stream=null,recChunks=[],recTick=null,recStart=0,recType='audio/webm';
async function startRecording(){ui.voiceError='';if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){ui.voiceError='Gravação indisponível neste navegador. Use HTTPS ou localhost e confira a permissão do microfone.';render();return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});recChunks=[];recType=MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?'audio/webm;codecs=opus':MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':'';recorder=new MediaRecorder(stream,recType?{mimeType:recType}:undefined);recorder.ondataavailable=e=>{if(e.data.size>0)recChunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(recChunks,{type:recorder?.mimeType||'audio/webm'});if(ui.recordUrl)URL.revokeObjectURL(ui.recordUrl);ui.recordUrl=URL.createObjectURL(blob);stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;ui.recording=false;clearInterval(recTick);render();toast('Gravação pronta para ouvir ou salvar.')};recorder.start();ui.recording=true;ui.recordElapsed=0;recStart=Date.now();render();recTick=setInterval(()=>{ui.recordElapsed=Math.floor((Date.now()-recStart)/1000);let t=document.getElementById('record-timer');if(t)t.textContent=formatSecs(ui.recordElapsed);if(ui.recordElapsed>=600)stopRecording()},260)}catch(e){stream?.getTracks().forEach(t=>t.stop());stream=null;ui.voiceError='Não foi possível usar o microfone. Verifique permissão e disponibilidade do dispositivo.';render()}}
function stopRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();else{ui.recording=false;clearInterval(recTick);render()}}
function downloadBlob(content,filename,mime){const blob=content instanceof Blob?content:new Blob([content],{type:mime});let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
